 const project=()=>store.value.document,model=()=>project().security,ts=()=>threats(project()),cs=()=>controlRecords(project()),findings=()=>memo.findings(project()),milestones=()=>memo.milestones(project());
 const currentThreat=()=>threat(project(),bridge.state.selected)||threat(project(),control(project(),bridge.state.selected)?.threatIds[0])||ts().find(t=>t.targetIds.includes(bridge.state.selected))||threat(project(),activeThreat)||inLens(ts())[0]||ts()[0],currentControl=()=>control(project(),bridge.state.selected)||relatedControls(project(),bridge.state.selected)[0]||cs().find(c=>c.targetIds.includes(bridge.state.selected))||control(project(),activeControl)||inLens(cs())[0]||cs()[0];
 const current=()=>control(project(),bridge.state.selected)||threat(project(),bridge.state.selected)||securityTarget(project(),bridge.state.selected),selected=()=>bridge.getNode(bridge.state.selected),label=id=>securityTarget(project(),id)?.ref||threat(project(),id)?.ref||control(project(),id)?.ref||id;
 const chapterContext=()=>({work:'Describe the exposure, design its controls, and name who owns the remaining risk.',model:'Trace a threat through its affected objects, intended controls, and evidence gaps.',validate:'Resolve unsupported protection claims, stale evidence, and missing risk treatments.',output:'Carry enforcement points, runtime obligations, and unresolved risk into deployment design.'}[bridge.state.tab]);
 function error(message,conflict=false){const e=document.querySelector('#sec-dialog-error')||document.querySelector('#sec-page-error');if(e){e.hidden=false;e.innerHTML=esc(message)+(conflict?B('reload','Load latest project'):'');e.scrollIntoView({block:'nearest'})}bridge.toast(message)}
 function close(force=false,{restoreFocus=true}={}){const e=document.querySelector('.sec-dialog');if(!e)return;if(dirty&&!force){e.querySelector('.l-discard').hidden=false;e.querySelector('[data-sec-action=keep]')?.focus();return}closeDialog(e,{restoreFocus});dirty=false}
 function dialog(title,body,type,extra={}){if(presentAssistant(type,title,body))return;close(true);context={type,...extra};const e=openDialog({className:'l-dialog sec-dialog',labelledBy:'sec-dialog-title',html:'<header><div><span class="eyebrow">Chapter 09 / '+esc(bridge.state.tab)+'</span><h2 id="sec-dialog-title">'+esc(title)+'</h2></div>'+B('close','×','',{'aria-label':'Close dialog'})+'</header><div id="sec-dialog-error" class="l-error" role="alert" hidden></div>'+body+'<div class="l-discard" hidden><p>Discard your unsaved changes?</p>'+B('keep','Keep editing')+B('discard','Discard changes')+'</div>',onCancel:()=>close(),closeSelector:null});opener=e.opener;if(['sol','mind'].includes(type))window.aiwInterfaceImpact?.decorateAssistant(e,type);}
 function pause(){clearTimeout(timer);timer=null;if(lab)lab.playing=false}
 // A type with a prefix of its own (record.retire, record.restore: the one lifecycle family) is sent as it is.
 async function send(type,payload={},message='Saved to your private project.',after){if(busy)return false;pause();let command={type:type.includes('.')?type:'security.'+type,payload};const editor=document.querySelector('.sec-dialog');if(editor){command=await reviewChangeInDialog(editor,project(),command);if(!command)return false;}busy=true;setDialogBusy(document.querySelector('.sec-dialog'),'saving');const from=opener,ids=[payload.id];try{const result=await store.command(command);if(result.selected)ids.unshift(result.selected);close(true,{restoreFocus:false});ghost=null;if(result.selected){bridge.state.selected=result.selected;if(threat(project(),result.selected))activeThreat=result.selected;if(control(project(),result.selected))activeControl=result.selected;bridge.state.visible=[...new Set([...bridge.state.visible,'security'])]}bridge.persist();bridge.render();bridge.toast(message);after?.();returnFocus(from,{ids,attributes:['data-select','data-sec-id']});return true}catch(e){error(e.message,e.conflict);return false}finally{busy=false;setDialogBusy(document.querySelector('.sec-dialog'),false)}}
 function step(index){const f=document.querySelector('.sec-dialog form');if(!f)return;f.querySelectorAll('[data-sec-panel]').forEach(e=>e.hidden=Number(e.dataset.secPanel)!==index);f.querySelectorAll('[data-sec-step]').forEach(e=>{e.classList.toggle('active',Number(e.dataset.secStep)===index);e.setAttribute('aria-pressed',String(Number(e.dataset.secStep)===index))});f.querySelector('[data-sec-panel="'+index+'"] input,[data-sec-panel="'+index+'"] textarea,[data-sec-panel="'+index+'"] select')?.focus()}
 const steps=names=>'<nav class="l-steps" aria-label="Security editing steps">'+names.map((s,i)=>B('step',s,i===0?'active':'',{'data-sec-step':i,'aria-pressed':i===0})).join('')+'</nav>';
 function targetChecks(ids=[]){const records=securityTargets(project());return '<div class="sec-target-checks">'+['Interface','Data','Application','Realization','Capability','Trust boundary'].map(kind=>'<details'+(['Interface','Data'].includes(kind)||records.some(r=>r.targetKind===kind&&ids.includes(r.id))?' open':'')+'><summary>'+esc(kind)+' objects</summary><fieldset class="l-checks"><legend class="sr-only">'+esc(kind)+' scope</legend>'+records.filter(r=>r.targetKind===kind).map(r=>'<label><input type="checkbox" name="targetIds" value="'+esc(r.id)+'"'+(ids.includes(r.id)?' checked':'')+'><span><b>'+esc(r.ref)+' · '+esc(r.title)+'</b></span></label>').join('')+'</fieldset></details>').join('')+'</div>'}
 function threatForm(t={}){return '<form id="sec-editor">'+steps(['Scenario','Exposure','Priority'])+'<section data-sec-panel="0">'+fThreat('title',t.title)+fThreat('category',t.category??'',{options:[['','Not stated'],...THREAT_CATEGORIES.map(v=>[v,v])]})+fThreat('actor',t.actor)+fThreat('scenario',t.scenario)+fThreat('consequence',t.consequence)+B('step','Next: affected objects','',{'data-sec-step':1})+'</section><section data-sec-panel="1"><p>Link the exact objects this threat affects. The same references stay visible across the architecture.</p>'+targetChecks(t.targetIds)+B('step','Next: priority and owner','',{'data-sec-step':2})+'</section><section data-sec-panel="2">'+fThreat('owner',t.owner)+fThreat('priority',t.priority??'',{options:[['','Not stated'],...PRIORITIES.map(v=>[v,v])]})+(t.prioritySource?'<p class="l-note">This priority was set by '+esc(t.prioritySource==='person'?'a person':t.prioritySource==='rule'?'a rule':'a source band')+'. A change you make here is recorded as yours.</p>':'')+fThreat('priorityBasis',t.priorityBasis)+fThreat('grounds',groundText(t))+'<p class="l-note">Priority is your qualitative judgement. Explain exposure and business impact; AIW does not multiply unexplained scores.</p>'+fThreat('assumptions',t.assumptions)+fThreat('assumptionsResolved',t.assumptionsResolved)+'</section>'+end('Save threat scenario')+'</form>'}
 function controlForm(c={},proposed=false){return '<form id="sec-control-form">'+steps(['Design','Scope','Operate & test'])+'<section data-sec-panel="0">'+fControl('title',c.title)+fControl('category',c.category||CONTROL_CATEGORIES[0],{options:CONTROL_CATEGORIES.map(v=>[v,v])})+fControl('purpose',c.purpose)+fControl('owner',c.owner)+fControl('enforcement',c.enforcement)+fControl('mechanism',c.mechanism)+'<div class="l-form-grid">'+fControl('makerRole',c.makerRole)+fControl('checkerRole',c.checkerRole)+'</div><p class="l-note">For a dual control, the role that makes the change and the role that checks it, which one person cannot hold together.</p>'+parameterRows(c)+B('step','Next: control scope','',{'data-sec-step':1})+'</section><section data-sec-panel="1">'+fControl('threatIds',c.threatIds||[],{options:ts().map(t=>({id:t.id,strong:t.ref+' · '+t.title,title:''}))})+'<p>Choose the objects this control actually protects. A linked threat must share an affected object.</p>'+targetChecks(c.targetIds)+B('step','Next: operation and testing','',{'data-sec-step':2})+'</section><section data-sec-panel="2">'+fControl('failureMode',c.failureMode||'Unspecified',{options:['Unspecified','Deny or contain','Detect and respond','Explicit exception'].map(v=>[v,v])})+fControl('failureResponse',c.failureResponse)+fControl('telemetry',c.telemetry)+fControl('verificationPlan',c.verificationPlan)+fControl('operatingObligations',c.operatingObligations)+fControl('grounds',groundText(c))+'<details><summary>Assumptions</summary>'+fControl('assumptions',c.assumptions)+fControl('assumptionsResolved',c.assumptionsResolved)+'</details>'+(proposed?fControl('reviewed',false):'')+'</section>'+(proposed?B('preview-edits','Preview edited ghost'):'')+end(proposed?'Accept reviewed control design':'Save control design')+'</form>'}
 // Round 12 (GR-SEC-04): a control's parameters, one row each with two spare rows.
 function parameterRows(c){return '<fieldset class="sec-parameters"><legend>Parameters</legend><p class="l-note">A limit, a threshold or a period the control keeps, with its value and basis.</p>'+[...(c.parameters||[]),{},{}].map((x,i)=>'<div class="l-form-grid">'+fControl('parameterName',x.name||'',{item:i,label:'Parameter '+(i+1)})+fControl('parameterValue',x.value||'',{item:i})+fControl('parameterUnit',x.unit||'',{item:i})+fControl('parameterBasis',x.basis||'',{item:i})+'</div>').join('')+'</fieldset>';}
 function rawForm(f){const fd=new FormData(f),raw=Object.fromEntries(fd);if(f.id==='sec-control-form'){const rows=[...new Set([...fd.keys()].filter(k=>k.startsWith('parameterName-')).map(k=>k.slice(14)))],get=k=>String(fd.get(k)??'');raw.parameters=rows.filter(i=>get('parameterName-'+i).trim()).map(i=>({name:get('parameterName-'+i),value:get('parameterValue-'+i),unit:get('parameterUnit-'+i),basis:get('parameterBasis-'+i)}));for(const k of Object.keys(raw))if(/^parameter(?:Name|Value|Unit|Basis)-/.test(k))delete raw[k];}for(const key of ['reviewed','assumptionsResolved','acknowledge'])raw[key]=fd.has(key);for(const key of ['targetIds','threatIds'])raw[key]=fd.getAll(key);if('grounds' in raw){Object.assign(raw,groundsOf(raw.grounds));delete raw.grounds;}return raw}
 function editThreat(id=currentThreat()?.id){const t=threat(project(),id),target=securityTarget(project(),bridge.state.selected);dialog(t?'Edit '+t.ref+' threat':'New threat scenario',threatForm(t||{targetIds:target?[target.id]:[]}), 'threat',{id:t?.id});step(0)}
