 function intake(){dialog('What Chapter 9 inherits',badge(interfaceHandoffCurrent(project())?'Current Chapter 8 handoff':'Chapter 8 working model · handoff needs review',!interfaceHandoffCurrent(project()))+'<p>'+project().interfaces.contracts.length+' contracts, '+project().interfaces.data.length+' data definitions, and '+project().technology.boundaries.length+' trust boundaries continue the same project.</p><p>'+(!ts().length&&!cs().length?'No threat or control is recorded yet. Review the inherited interfaces, data and trust boundaries, then add applicable protection requirements.':[...ts(),...cs()].some(r=>r.origin==='reference')?'Reference threats and controls are illustrative. Confirm their scope with the accountable owners.':'Review each recorded threat and control against its source and accountable owner.')+'</p><form id="sec-intake-form">'+end('Mark inherited inputs reviewed')+'</form>','intake')}
 function pick(id){pause();ghost=null;bridge.state.selected=id;if(threat(project(),id))activeThreat=id;if(control(project(),id))activeControl=id;bridge.state.visible=[...new Set([...bridge.state.visible,'security'])];bridge.persist();bridge.render()}
 function setStage(value){stage=value;if(value==='threats')pick(currentThreat()?.id);else if(value==='controls')pick(currentControl()?.id);else bridge.render()}
