 function recordEvidence(id=currentControl()?.id,kind='design'){const c=control(project(),id);if(!c)return;activeControl=c.id;dialog('Record evidence · '+c.ref,'<p>'+esc(c.title)+'</p><p>Identify the evidence and observed result. Recording a reference does not independently verify its contents.</p><form id="sec-evidence-form">'+fEvidence('kind',kind,{options:EVIDENCE_KINDS.map(k=>[k,evidenceName(k)])})+fEvidence('result','partial',{options:[['pass','Pass / meets the stated review criteria'],['partial','Partial / limitations remain'],['fail','Fail / expected result not met']]})+fEvidence('reviewer','')+fEvidence('reference','')+fEvidence('observations','')+fEvidence('reviewed',false)+end('Record evidence')+'</form>','evidence',{id:c.id,stamp:controlStamp(project(),c)})}
