 function startSimulation(mode='planned'){pause();const t=currentThreat();lab={id:t.id,mode,result:simulateSecurity(project(),t.id,mode),stamp:threatStamp(project(),t),step:0,visited:[0],playing:false};ghost=null;close(true);bridge.state.selected=t.id;bridge.state.visible=['security','interface','data','physical','technology'];bridge.state.focus=false;bridge.state.zoom=1;bridge.state.pan={x:0,y:0};bridge.setTab('model')}
