 function failureSurface(){if(!lab)return '<div class="t-failure-invite"><div><span class="eyebrow">Security design walkthrough / Simulation</span><p>Follow a threat through intended enforcement, then make the control unavailable to inspect the written response.</p></div>'+B('simulate','Explore the selected threat','gold')+'</div>';const t=threat(project(),lab.id),s=lab.result.steps[lab.step];return '<div class="sec-lab-head"><div><span class="eyebrow">'+esc(t.ref)+' / Design simulation</span><h3>'+esc(t.title)+'</h3></div>'+badge(labCurrent()?'Current model':'Changes require a restart',!labCurrent())+'</div><nav class="sec-lab-modes" aria-label="Security scenario condition">'+B('mode','Planned control response',lab.mode==='planned'?'active':'',{'data-sec-mode':'planned'})+B('mode','Control unavailable',lab.mode==='unavailable'?'active':'',{'data-sec-mode':'unavailable'})+'</nav><nav class="sec-lab-stages" aria-label="Security walkthrough stages">'+lab.result.steps.map((s,i)=>B('lab-step',(lab.visited.includes(i)?'✓ ':'')+String(i+1)+'. '+s.title,lab.step===i?'active':'',{'data-sec-step':i})).join('')+'</nav><div class="sec-actions">'+B('lab-restart','Restart')+B('lab-next','Step','',lab.step>=3||!labCurrent()?{disabled:'disabled'}:{})+B('lab-play',lab.playing?'Pause':'Play')+B('record-simulation','Record walkthrough','gold',lab.visited.length===4&&labCurrent()?{}:{disabled:'disabled'})+B('close-lab','Close walkthrough','text-button')+'</div><div class="sec-lab-result"><span class="eyebrow">Step '+(lab.step+1)+' of 4</span><h3>'+esc(s.title)+'</h3><p>'+esc(s.detail)+'</p></div><p class="l-note">Recording requires visiting all four stages against an unchanged saved model. This follows written policies. It does not execute an attack, test a live system, or prove a control works.</p>'}
